 3	/**
 4	 * Tests for gui/public/api-client.js — run log, server-info, orchestrator,
 5	 * knowledge, chunk, and model registry methods.
 6	 *
 7	 * Uses jsdom + vm.runInThisContext to load the browser-side script, then mocks
 8	 * globalThis.fetch to assert the URLs and options that API methods produce.
 9	 */
10	
11	import { describe, it, expect, beforeAll, afterEach, vi } from 'vitest';
12	import { readFileSync } from 'node:fs';
13	import { join } from 'node:path';
14	import vm from 'node:vm';
15	
16	// ---------------------------------------------------------------------------
17	// Load client script
18	// ---------------------------------------------------------------------------
19	
20	const publicDir = join(__dirname, '../../gui/public');
21	const apiClientJs = readFileSync(join(publicDir, 'api-client.js'), 'utf-8');
22	
23	// Execute once so the API var is available globally (as in a browser)
24	beforeAll(() => {
25	  vm.runInThisContext(apiClientJs);
26	});
27	
28	// Remove the fetch mock after every test so that residual mocks from one test
29	// cannot bleed into the next test's setup or assertion phase.
30	afterEach(() => {
31	  delete (globalThis as unknown as Record<string, unknown>)['fetch'];
32	});
33	
34	// Declare globalThis.API for TypeScript
35	declare global {
36	  // eslint-disable-next-line no-var
37	  var API: {
38	    getRunLogs: (repo: string, slug: string) => Promise<unknown>;
39	    getRunLogEntries: (repo: string, slug: string, filename: string, afterLine?: number) => Promise<unknown>;
40	    [key: string]: (...args: unknown[]) => Promise<unknown>;
41	  };
42	}
43	
44	// ---------------------------------------------------------------------------
45	// Helpers
46	// ---------------------------------------------------------------------------
47	
48	/**
49	 * Installs a mock `fetch` on globalThis that resolves with the provided JSON
50	 * body and records the most-recent call arguments.
51	 */
52	function mockFetch(responseBody: unknown = null, status = 200) {
53	  const calls: { url: string; opts: RequestInit }[] = [];
54	  const mockFn = vi.fn(async (url: string, opts: RequestInit) => {
55	    calls.push({ url, opts });
56	    return {
57	      ok: status >= 200 && status < 300,
58	      status,
59	      json: async () => responseBody,
60	    };

