46	/** Return true when the working copy has any unsaved changes vs the snapshot.
47	 *
48	 * Comparison is index-based (position i in mrModels vs position i in mrOriginal),
49	 * not ID-based. This is correct because mrDoSave() submits activeModels in
50	 * iteration order and the server reflects that same order back in result.models.
51	 * If the server ever returns models in a different order (e.g. alphabetical sort),
52	 * this function would always return true after a save. Should that happen,
53	 * replace this loop with an ID-keyed map comparison instead.
54	 */
55	function mrHasChanges() {
56	  if (!mrModels || !mrOriginal) return false;
57	  if (mrModels.length !== mrOriginal.length) return true;
58	  for (var i = 0; i < mrModels.length; i++) {
59	    var a = mrModels[i];
60	    var b = mrOriginal[i];
61	    if (a.id !== b.id || a.name !== b.name || a.slug !== b.slug || a.cc_model !== b.cc_model || a._deleted !== b._deleted) return true;
